using GastricCancerDetection.Application.Interfaces; using GastricCancerDetection.Infrastructure.Persistence; using GastricCancerDetection.Domain.Entities; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Infrastructure.Services; public class CfDNADetectabilityService:ICfDNADetectabilityService { private readonly GastricCancerDbContext _db; public CfDNADetectabilityService(GastricCancerDbContext db)=>_db=db; public async Task CalculateAsync(int runId,CancellationToken ct=default){var candidates=await _db.Candidates.Where(x=>x.AnalysisRunId==runId).ToListAsync(ct); foreach(var c in candidates){var signal=Clamp(c.BiologicalEvidence??0);var dilution=Clamp((c.RegionSizeBp??1)>0?Math.Min(1,Math.Log10((c.RegionSizeBp??1)+1)/6):0);var depth=Clamp((c.FeatureType=="ArmLevelCNA"||c.FeatureType=="NonCodingHotspot")?0.7:0.3);var redundancy=Clamp(Math.Min(1,(c.RegionSizeBp??1)/10000.0));var score=.25*signal+.25*dilution+.20*depth+.15*redundancy+.15*Clamp(c.EarlyStageScore??0);c.CfDNADetectabilityScore=score;var row=await _db.CfDNADetectabilityScores.FirstOrDefaultAsync(x=>x.AnalysisRunId==runId&&x.CandidateId==c.CandidateId,ct); if(row==null){row=new CfDNADetectabilityScore{CandidateId=c.CandidateId,AnalysisRunId=runId};_db.CfDNADetectabilityScores.Add(row);} row.RegionSizeBp=c.RegionSizeBp;row.SignalStrength=signal;row.DilutionResistance=dilution;row.LowDepthFeasibility=depth;row.RegionalRedundancy=redundancy;row.EarlyStageScore=c.EarlyStageScore;row.CancerSpecificityScore=c.CancerSpecificityScore;row.LiteratureWhitespace=c.LiteratureWhitespace;row.ValidationGap=c.ValidationGap;row.BiologicalSupport=c.BiologicalEvidence;row.TechnicalFeasibility=depth;row.CfDNADetectabilityScoreValue=score;row.ModelVersion="cfDNA-in-silico-v1";} await _db.SaveChangesAsync(ct);} static double Clamp(double x)=>Math.Max(0,Math.Min(1,x)); }
